<template>
    <div class="home-container">
        <div class="main" ref="main" :style="{ '--cols': gridColumn }">
            <div class="carousel">
                <div class="inner">
                    <MyCarousel :bannerList="bannerList"></MyCarousel>
                </div>
            </div>
            <VideoList v-for="(item) in computedHeadVideoList" :isSpecial="item && item.type != 'normal'" ref="videoListRefs"
                :key="item.id" :videoItem="item">
            </VideoList>
            <VideoList :isSpecial="headSpecialVideoList[0] && headSpecialVideoList[0].type != 'normal'" ref="videoListRefs"
                :videoItem="headSpecialVideoList[0] || {}">
            </VideoList>
            <VideoList v-for="(item) in renderList" :isSpecial="item.type != 'normal'" ref="videoListRefs"
                :key="item.id" :videoItem="item">
            </VideoList>
            <div class="loading-item" ref="loadingItemRef"></div>
            <div class="loading-item" v-for="value in gridColumn * 3 - 1" :key="value"></div>
        </div>
    </div>
</template>

<script>
import MyCarousel from "@/components/Carousel.vue";
import { getBanner, getVideoList, getSpecialVideoList, getHeadVideoList } from "@/api/home";
import VideoList from "@/views/home/VideoList.vue";
export default {
    name: "MyHome",
    components: {
        MyCarousel,
        VideoList
    },
    data() {
        return {
            bannerList: [],
            lastResizeDate: 0,
            videoList: [],
            finalHeight: 0,
            specialVideoList: [],
            gridColumn: 5,
            requestPage: 1,
            requestSpecialPage: 1,
            requestSpecialLimit: 1,
            loading: false,
            observer: null,
            key: false, // 是否是移动端
            hasMore: true,
            lastScrollTop: 0,
            lastDocumentHeight: 0,
            headVideoList: [],
            headSpecialVideoList: [],
            headRequestPage: 1,
        }
    },
    mounted() {
        this.handelColumn(window.innerWidth);
        window.addEventListener("resize", this.handleResize);
        window.addEventListener("scroll", this.handleScroll);

        this.$nextTick(() => {
            this.initObserve();
        });
    },
    beforeDestroy() {
        this.$bus.$off("resize", this.handelColumn);
        window.removeEventListener("resize", this.handleResize);
        window.removeEventListener("scroll", this.handleScroll);
        if (this.observer) {
            this.observer.disconnect();
        }
    },
    async created() {
        this.$bus.$on("resize", this.handelColumn);
        const res = await this.fetchData();
        this.bannerList = res;

        const width = typeof window !== 'undefined' ? window.innerWidth : 1920;
        this.gridColumn = width < 1410 ? 4 : 5;
        this.key = width < 1410;

        this.headVideoList = await this.fetchHeadDataList();
        this.headSpecialVideoList = await this.fetchSpecialVideoList(1, 1);
        this.requestPage++;
        this.requestSpecialPage++;
    },
    computed: {
        renderList() {
            return this.buildRenderList();
        },
        requestLimit() {
            return (this.gridColumn - 1) * 3;
        },
        computedHeadVideoList() {
            console.log("computed");
            return this.headVideoList.slice(0, (this.gridColumn - 2) * 2 + this.gridColumn - 1);
        }
    },
    methods: {
        buildRenderList() {
            const { videoList, specialVideoList, gridColumn } = this;
            const result = [];

            let vIndex = 0;
            let sIndex = 0;

            const videos = [...videoList];

            // 前三行已独立渲染，这里只负责渲染后三行及之后的内容
            // 每行排 (gridColumn - 1) 个普通视频，最后插入一个特殊视频
            const videosPerRow = gridColumn - 1;
            while (vIndex + videosPerRow <= videos.length && sIndex < specialVideoList.length) {
                // 普通项
                const rowItems = videos.slice(vIndex, vIndex + videosPerRow);
                result.push(...rowItems);
                vIndex += videosPerRow;
                // 特殊项
                result.push(specialVideoList[sIndex]);
                sIndex++;
            }

            return result;
        },
        async fetchData() {
            const res = await getBanner();
            return res;
        },
        async fetchVideoList(page, limit) {
            const res = await getVideoList(page, limit);

            return res;
        },
        async fetchSpecialVideoList(page, limit) {
            const res = await getSpecialVideoList(page, limit);
            return res;
        },
        async fetchHeadDataList() {
            const res = await getHeadVideoList(this.headRequestPage, 10);
            this.headRequestPage++;
            return res;
        },
        initObserve() {
            this.observer = new IntersectionObserver(
                (entries) => {
                    const entry = entries[0];
                    if (entry.isIntersecting) {
                        if (!this.loading) {
                            this.loadMore();
                        }
                    }
                },
                {
                    rootMargin: "100px 0px",
                    threshold: 0.5,
                }
            )
            this.observer.observe(this.$refs.loadingItemRef);
        },
        async loadMore() {
            this.loading = true;
            const videoList = await this.fetchVideoList(this.requestPage, this.requestLimit);
            this.videoList = [...this.videoList, ...videoList];
            const specialVideoList = await this.fetchSpecialVideoList(this.requestSpecialPage, 3);
            this.specialVideoList = [...this.specialVideoList, ...specialVideoList];
            this.requestPage++;
            this.requestSpecialPage++;
            this.loading = false;
            console.log(videoList, specialVideoList);
        },
        handelColumn(width) {
            const newKey = width < 1410;
            const newColumn = newKey ? 4 : 5;
            if (newKey !== this.key) {
                this.key = newKey;
                this.gridColumn = newColumn;
            }
        },
        handleResize() {
            const now = Date.now();
            if (now - this.lastResizeDate < 150) return;
            requestAnimationFrame(() => {
                this.$bus.$emit("resize", window.innerWidth);
                this.lastResizeDate = Date.now();
            })
        },
    },
}
</script>



<style lang="less" scoped>
.main {
    --gap: 20px;
    width: 85%;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(var(--cols), 1fr);
    gap: var(--gap);

    @media screen and (max-width: 1605px) {
        width: 90%;

    }

    @media screen and (max-width: 1444px) {
        width: 93%;

    }

    @media screen and (max-width: 1366px) {
        width: 95%;
    }

    .carousel {
        grid-area: 1 / 1 / 3 / 3;
        background: #fff;
        border-radius: 8px;
        overflow: hidden;

        .inner {
            width: 100%;
            height: calc(88% - var(--gap));
        }
    }

    .loading-item {
        background: #f5f5f5;
        border-radius: 8px;
        min-height: 200px;
    }
}
</style>
