<template>
    <div class="video-list" ref="videoList" >
        <div class="card">
            <div class="inner">
                <div class="img" ref="img">
                    <router-link :to="'/video/'+videoItem.id" target="_blank">
                        <img :src="videoItem.img" alt="">
                    </router-link>
                    <!-- <img :src="videoItem.img" alt="">
                    -->
                    <div class="shadow">
                        <div class="right" v-if="videoItem.type === 'normal'">
                            <span>{{ handelDuration(videoItem.duration) }}</span>
                        </div>
                        <div class="left">
                            <div class="views video-inner-item">
                                <Icons type="views" :size="14" />
                                <span>{{ handelBigNumber(videoItem.views) }}</span>
                            </div>
                            <div class="comments video-inner-item" v-if="videoItem.type === 'normal'">
                                <Icons type="danmu" :size="14" />
                                <span>{{ handelBigNumber(videoItem.comments) }}</span>
                            </div>
                        </div>
                    </div>

                </div>
                <div class="info">
                    <div class="title">
                        <router-link :to="'/video/'+videoItem.id" target="_blank">
                            {{ videoItem.title }}</router-link>
                    </div>
                    <div class="detail">
                        <div class="author">{{ videoItem.authordetail?.name || videoItem.author }}</div>
                        <div class="time" v-if="videoItem.createDate">{{ formatDate(new Date(parseInt(videoItem.createDate)), "yyyy-MM-dd") }}</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import Icons from "@/components/Icons.vue";
import formatDate from "@/utils/formatDate";
export default {
    name: 'VideoList',
    components: {
        Icons
    },
    data() {
        return {
            persentHeight: 0,
            lastResizeDate: 0,
        }
    },
    props: {
        videoItem: {
            type: Object,
            default: () => { }
        },
        isSpecial:{
            type: Boolean,
            default: false
        }
    },
    mounted() {
        // 子组件不再主动计算，由父组件通过 ref 调用
    },
    computed:{
        
    },
    methods: {
        computedHeight() {
            console.log("comp");
            const imgHeight = this.$refs.img.getBoundingClientRect().height;
            const wrapperHeight = this.$refs.videoList.getBoundingClientRect().height;
            return imgHeight + wrapperHeight;
        },
        // handelResize() {
        //     const now = Date.now();
        //     if (now - this.lastResizeDate < 150) return;
        //     requestAnimationFrame(() => {
        //         this.computedHeight();
        //         this.lastResizeDate = Date.now();
        //     })
        // },
        handelBigNumber(comments) {
            const result = parseInt(comments) / 10000;
            if (result >= 1) {
                return result.toFixed(1) + "万";
            }
            return comments;
        },
        handelDuration(duration) {
            let max = new Date(duration);
            let maxObj = {};
            maxObj.maxSecond = Math.floor(max % 60);
            maxObj.maxMinute = Math.floor(max % 60);
            maxObj.maxHour = Math.floor(max / 3600);
            for (const key in maxObj) {
                if (maxObj[key] < 10) {
                    maxObj[key] = "0" + maxObj[key];
                }
                // showMaxWord += maxObj[key];
            }
            if (maxObj.maxHour == 0) {
                return `${maxObj.maxMinute}:${maxObj.maxSecond}`;
            }
            return `${maxObj.maxHour}:${maxObj.maxMinute}:${maxObj.maxSecond}`;
        },
        formatDate
    }
}
</script>

<style lang="less" scoped>
@import "~@/views/home/videolist.css";

.video-list {
    width: 100%;
    height: 100%;
    border-radius: 10px;
    overflow: hidden;
    
    .card {
        position: relative;
        padding-top: 88%;
        width: 100%;
        height: 0;

        .inner {
            position: absolute;
            top: 0;
            left: 0;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: flex;
            flex-direction: column;
            gap: 5px;

            .img {
                width: 100%;
                height: 65%;
                position: relative;
                border-radius: 10px;
                overflow: hidden;
                font-size: 13px;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: cover;
                }

                .shadow {
                    position: absolute;
                    bottom: 0;
                    left: 0;
                    width: 100%;
                    height: 20%;
                    // 黑色从下至上的渐变 由深到浅透明
                    background: -webkit-linear-gradient(90deg, #000000, #00000000);

                    /* Chrome 10-25, Safari 5.1-6 */
                    .right {
                        position: absolute;
                        bottom: 50%;
                        transform: translateY(50%);
                        right: 5%;
                        color: var(--video_inner_word_color);
                        text-align: center;
                    }

                    .left {
                        position: absolute;
                        bottom: 50%;
                        transform: translateY(50%);
                        left: 5%;
                        color: var(--video_inner_word_color);
                        border-radius: 50%;
                        display: flex;
                        align-items: center;
                        gap: 10px;

                        .video-inner-item {
                            display: flex;
                            align-items: center;
                            gap: 5px;
                        }
                    }
                }

            }

            .info {
                flex: 1 auto;
                display: flex;
                justify-content: space-evenly;
                flex-direction: column;
                gap: 10px;

                .title {
                    font-size: 16px;
                    color: var(--video_title_word_color);
                }

                .detail {
                    display: flex;
                    font-size: 14px;
                    font-weight: normal;
                    gap: 5px;
                    color: var(--video_detail_word_color);
                }
            }
        }
    }
}
</style>