<template>
    <div class="carousel-container" ref="carouselContainer">
        <div class="carousel-item">
            <div class="inner" @transitionend="handeltrans" :class="{ 'hasTransition': isTransition }"
                :style="{ transform: `translateX(${-index * 100}%)` }">
                <div class="carousel-item-content" ref="carouselItemContent" v-for="(item, i) in computedImages"
                    :key="i">
                    <img :src="item" alt="">
                </div>
            </div>
        </div>
        <div class="carousel-bottom" :style="{
            backgroundColor: bgColor[index],
            boxShadow: `0px -25px 36px 30px ${bgColor[index]}`,
            zIndex: 100
        }">
            <div class="choose-radio">
                <div class="radio-item" :class="{ 'active': index - 1 === i }" @click="turn(i + 1)"
                    v-for="(item, i) in radioList" :key="i"></div>
            </div>
            <div class="arrow-left arrow" @click="turnLeft">
                <Icons type="left" :size="18" color="#fff" />
            </div>
            <div class="arrow-right arrow" @click="turnRight">
                <Icons type="right" :size="18" color="#fff" />
            </div>
            <div class="description">
                {{ descList[index - 1] }}
            </div>
        </div>
    </div>
</template>

<script>
import Icons from "@/components/Icons.vue"
export default {
    name: "MyCarousel",
    components: {
        Icons
    },
    props: {
        bannerList: {
            type: Array,
            default: () => []
        }
    },
    data() {
        return {
            index: 1,
            innerWidth: 0,
            isTransition: true,
            transitioning: false
        }
    },
    created() {
        window.addEventListener('resize', this.calculateCarouselHeight)
    },
    beforeDestroy() {
        window.removeEventListener('resize', this.calculateCarouselHeight)
    },
    mounted() {
        this.calculateCarouselHeight()
    },
    computed: {
        bgColor() {
            let bgColorList = this.bannerList.map(item => item.background);
            bgColorList.unshift(bgColorList[bgColorList.length - 1])
            bgColorList.push(bgColorList[1])

            return bgColorList
        },
        radioList() {
            let radioList = new Array(this.bannerList.length).fill(1)
            return radioList
        },
        computedImages() {
            let imageList = this.bannerList.map(item => item.image);
            imageList.unshift(imageList[imageList.length - 1])
            imageList.push(imageList[1])
            return imageList
        },
        descList() {
            let descList = this.bannerList.map(item => item.description);
            return descList
        }
    },
    methods: {
        calculateCarouselHeight() {
            this.$forceUpdate()
        },
        handeltrans() {
            if (this.index === this.bannerList.length + 1) {
                this.isTransition = false
                this.index = 1
            }
            if (this.index === 0) {
                this.isTransition = false
                this.index = this.bannerList.length
            }
            this.transitioning = false
        },
        turn(index) {
            if (index < 0) {
                index = this.computedImages.length - 1
            }
            if (index >= this.computedImages.length) {
                index = 0
            }
            this.index = index
        },
        turnLeft() {
            if (this.transitioning) return
            this.transitioning = true
            this.isTransition = true
            this.index--
        },
        turnRight() {
            if (this.transitioning) return
            this.transitioning = true
            this.isTransition = true
            this.index++
        },
        // onImageLoad() {
        //     if (this.$refs.carouselItemContent && this.$refs.carouselItemContent[0]) {
        //         this.innerWidth = this.$refs.carouselItemContent[0].getBoundingClientRect().width
        //     }
        // }
    }
}
</script>

<style lang="less" scoped>
.carousel-container {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: relative;
    border-radius: 7px;

    .carousel-item {
        width: 100%;
        height: 80%;
        display: flex;
        position: relative;

        .inner {
            position: absolute;
            width: 100%;
            left: 0px;
            display: flex;

            &.hasTransition {
                transition: all 0.3s ease-in-out;
            }

            .carousel-item-content {
                width: 100%;
                // height: 100%;
                flex-shrink: 0;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: cover;
                }
            }
        }
    }

    .bgColor {
        position: absolute;
        top: 0;
        left: 100%;
        width: 100%;
        height: 100%;
        flex-shrink: 0;
    }
}

.carousel-bottom {
    flex: 1;
    position: relative;
    @bottom: 20px;
    @left: 10px;

    .choose-radio {
        width: 100%;
        height: 20px;
        display: flex;
        position: absolute;
        align-items: center;
        left: @left;
        bottom: @bottom;

        .radio-item {
            @size: 10px;
            width: @size;
            height: @size;
            border-radius: 50%;
            background-color: #c1bfbfbe;
            margin: 0 5px;

            &.active {
                width: @size + 5px;
                height: @size + 5px;
                background-color: #fff;
            }
        }

    }

    .arrow {
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        z-index: 100;
        cursor: pointer;
        border-radius: 3px;
        box-sizing: border-box;
        padding: 7px;
        background-color: rgba(67, 67, 67, 0.5);

        &:hover {
            background-color: lightgray;
            color: #fff;
        }
    }

    .arrow-left {
        right: 50px;
        transform: translateY(-50%);
    }

    .arrow-right {
        right: 10px;
        transform: translateY(-50%);
    }

    .description {
        position: absolute;
        bottom: @bottom + 25px;
        left: @left + 5px;
        z-index: 100;
        color: #fff;
        font-size: 16px;
        font-weight: bold;
    }
}
</style>